<script setup lang="ts">
import PageHeader from '../components/PageHeader.vue'
import { computed, onMounted, ref } from 'vue'
import StudyChart from '../components/StudyChart.vue'
import MetricCard from '../components/MetricCard.vue'
import RingProgress from '../components/RingProgress.vue'
import AppIcon from '../components/AppIcon.vue'
import { api, errorText, type KnowledgePoint } from '../lib/api'
interface Statistic { start: string; end: string; timezone: string; summary: { practiceCount: number; wrongCount: number; accuracy: number; reviewsCompleted: number; reviewsSkipped: number; duePending: number; reviewCompletionRate: number; studySeconds: number }; trend: { day: string; practiceCount: number; wrongCount: number; reviewsCompleted: number; accuracy: number }[]; typeDistribution: { name: string; value: number }[]; reasonDistribution: { name: string; value: number }[]; knowledgeDistribution: { name: string; value: number }[]; weakPoints: KnowledgePoint[] }
const data = ref<Statistic | null>(null), days = ref(7), error = ref('')
async function load() { try { data.value = (await api.get<Statistic>('/statistics', { params: { days: days.value } })).data; error.value = '' } catch (e) { error.value = errorText(e) } }
const trend = computed(() => ({ tooltip: { trigger: 'axis' }, legend: { bottom: 0 }, grid: { left: 45, right: 16, top: 20, bottom: 60 }, xAxis: { type: 'category', data: data.value?.trend.map(x => x.day.slice(5)) }, yAxis: { type: 'value', minInterval: 1 }, series: [{ name: '练习数量', type: 'bar', barMaxWidth: 22, data: data.value?.trend.map(x => x.practiceCount) }, { name: '错题数量', type: 'line', data: data.value?.trend.map(x => x.wrongCount) }, { name: '复习完成', type: 'line', data: data.value?.trend.map(x => x.reviewsCompleted) }] }))
const accuracy = computed(() => ({ tooltip: { trigger: 'axis' }, grid: { left: 45, right: 16, top: 20, bottom: 40 }, xAxis: { type: 'category', data: data.value?.trend.map(x => x.day.slice(5)) }, yAxis: { type: 'value', min: 0, max: 100, axisLabel: { formatter: '{value}%' } }, series: [{ name: '练习正确率', type: 'line', connectNulls: false, data: data.value?.trend.map(x => x.practiceCount ? x.accuracy : null) }] }))
const pie = (values: { name: string; value: number }[]) => ({ tooltip: { trigger: 'item' }, legend: { bottom: 0, type: 'scroll' }, series: [{ type: 'pie', radius: ['42%','65%'], center: ['50%','43%'], label: { show: false }, data: values }] })
const distribution = computed(() => ({ tooltip: { trigger: 'axis' }, grid: { left: 110, right: 20, top: 16, bottom: 35 }, xAxis: { type: 'value', minInterval: 1 }, yAxis: { type: 'category', inverse: true, data: data.value?.knowledgeDistribution.map(x => x.name) }, series: [{ type: 'bar', barMaxWidth: 18, data: data.value?.knowledgeDistribution.map(x => x.value) }] }))
onMounted(load)
</script>
<template><PageHeader title="学习统计"><template #description><p class="muted">{{ data ? data.start + ' 至 ' + data.end + ' · ' + data.timezone : '正在读取学习统计…' }}</p></template><div class="segmented"><button :class="{ active: days === 7 }" :aria-pressed="days === 7" @click="days = 7; load()">7 天</button><button :class="{ active: days === 30 }" :aria-pressed="days === 30" @click="days = 30; load()">30 天</button></div></PageHeader><p v-if="error" class="error" role="alert">{{ error }}</p><template v-if="data"><div class="stat-grid"><MetricCard label="练习总数" :value="data.summary.practiceCount" unit="道" icon="pen" /><MetricCard label="练习错题" :value="data.summary.wrongCount" unit="道" icon="book" tone="amber" /><MetricCard label="练习正确率" :value="data.summary.practiceCount ? data.summary.accuracy + '%' : '—'" icon="target" /><MetricCard label="学习用时" :value="Math.round(data.summary.studySeconds / 60)" unit="分钟" icon="clock" tone="blue" /></div><div class="content-grid section-gap"><section class="panel visual-summary"><RingProgress :value="Math.max(0, data.summary.practiceCount - data.summary.wrongCount)" :total="data.summary.practiceCount" label="练习正确率" /><div><h2><AppIcon name="target" />练习质量</h2><p class="muted">正确 {{ Math.max(0, data.summary.practiceCount - data.summary.wrongCount) }} 道 · 错题 {{ data.summary.wrongCount }} 道</p></div></section><section class="panel visual-summary"><RingProgress :value="data.summary.reviewsCompleted" :total="data.summary.reviewsCompleted + data.summary.reviewsSkipped + data.summary.duePending" label="复习完成率" /><div><h2><AppIcon name="review" />复习完成情况</h2><p class="muted">已完成 {{ data.summary.reviewsCompleted }} · 跳过 {{ data.summary.reviewsSkipped }} · 到期未复习 {{ data.summary.duePending }}</p></div></section></div><div class="content-grid section-gap"><section class="panel"><h2>学习数量趋势</h2><StudyChart :option="trend" label="每日练习、错题和复习完成数量趋势"></StudyChart></section><section class="panel"><h2>正确率趋势</h2><StudyChart :option="accuracy" label="有练习记录日期的正确率"></StudyChart></section><section class="panel"><h2>错题类型</h2><StudyChart v-if="data.typeDistribution.length" :option="pie(data.typeDistribution)" label="错题类型分布"></StudyChart><p v-else class="empty">还没有错题分类记录。</p></section><section class="panel"><h2>错因分布</h2><StudyChart v-if="data.reasonDistribution.length" :option="pie(data.reasonDistribution)" label="用户确认的错因分布"></StudyChart><p v-else class="empty">还没有错因记录。</p></section><section class="panel"><h2>知识点关联题数</h2><StudyChart v-if="data.knowledgeDistribution.length" :option="distribution" label="每个知识点关联的题目数量，可同时关联多个知识点"></StudyChart><p v-else class="empty">题目录入后逐步建立分布。</p></section><section class="panel"><h2>最需巩固的知识点</h2><p v-if="!data.weakPoints.length" class="empty">完成练习后查看薄弱知识点。</p><div v-for="point in data.weakPoints" :key="point.id" class="progress-row"><div>{{ point.name }}<span>{{ point.mastery }}%</span></div><progress max="100" :value="point.mastery"></progress></div></section></div><section class="panel section-gap"><h2>每日记录</h2><div class="table-scroll"><table><thead><tr><th>日期</th><th>练习</th><th>错题</th><th>正确率</th><th>复习完成</th></tr></thead><tbody><tr v-for="row in data.trend" :key="row.day"><td>{{ row.day }}</td><td>{{ row.practiceCount }}</td><td>{{ row.wrongCount }}</td><td>{{ row.practiceCount ? row.accuracy + '%' : '—' }}</td><td>{{ row.reviewsCompleted }}</td></tr></tbody></table></div><p class="muted">复习完成率按有效复习、跳过及当前到期任务计算。掌握度按知识点及子节点的真实练习与复习正确率计算；同一记录只计一次。总学习用时 {{ Math.round(data.summary.studySeconds / 60) }} 分钟。</p></section></template></template>
